<script>
(()=>{
 const url=<?=json_encode($base.'/member/restaurant/orders/'.$order['id'].'/status')?>;
 const statusEl=document.getElementById('restaurantOrderStatusText');
 const messageEl=document.getElementById('restaurantOrderStatusMessage');
 const statusMessages={PENDING:'Your order has been received and is waiting for restaurant confirmation.',ACCEPTED:'The restaurant accepted your order.',PREPARING:'The restaurant is preparing your food.',READY:'Your order is ready.',ASSIGNED:'A delivery person has been assigned.',OUT_FOR_DELIVERY:'Your food is on the way.',DELIVERED:'Your order has been delivered.',COMPLETED:'Order completed.',CANCELLED:'This order was cancelled.',REJECTED:'The restaurant rejected this order.'};
 let current=<?=json_encode($status)?>;
